package br.com.nuvemtv;
import org.json.*;import org.junit.*;import static org.junit.Assert.*;
public class ChatHistoryTest {
 JSONObject message(String id,String sender,String stamp,String text){return Json.obj("messageId",id,"sender",sender,"timestamp",stamp,"contentPayload",Json.obj("content",Json.obj("parts",Json.arr(Json.obj("contentType","text","text",text)))));}
 @Test public void readsRealNestedPayloadAndOrdersBothPeople()throws Exception{ChatHistory h=new ChatHistory();h.targetXuid="123";h.merge(Json.obj("messages",Json.arr(message("2","123","2026-01-02T10:00:00Z","Olá"),message("1","456","2026-01-01T10:00:00Z","Oi"))),false);String s=h.render("Pessoa","Você","aguardando","vazio");assertTrue(s.indexOf("Oi")<s.indexOf("Olá"));assertTrue(s.contains("Você ·"));assertTrue(s.contains("Pessoa ·"));}
 @Test public void acceptedSendSurvivesDelayedFetchAndDeduplicatesOnSync()throws Exception{ChatHistory h=new ChatHistory();h.accepted(Json.obj("messageId","m1"),"Texto enviado");h.merge(Json.obj("messages",new JSONArray()),false);assertTrue(h.render("P","Você","aguardando","vazio").contains("aguardando"));h.merge(Json.obj("messages",Json.arr(message("m1","456","2026-01-01T10:00:00Z","Texto enviado"))),false);assertEquals(1,h.messages.size());assertFalse(h.render("P","Você","aguardando","vazio").contains("aguardando"));}
 @Test public void paginationIsBoundedAndDeletedContentIsHidden()throws Exception{ChatHistory h=new ChatHistory();h.merge(Json.obj("messages",Json.arr(message("1","123","2026","first")),"continuationToken","page2"),false);assertEquals("page2",h.continuation);h.merge(Json.obj("messages",Json.arr(message("2","123","2025","older")),"continuationToken",""),true);assertEquals(2,h.messages.size());assertEquals("",h.continuation);JSONObject deleted=message("2","123","2025","older");deleted.put("isDeleted",true);h.merge(Json.obj("messages",Json.arr(deleted)),false);assertFalse(h.render("P","Me","wait","empty").contains("older"));for(int i=0;i<150;i++)h.accepted(Json.obj("messageId","x"+i),"test");assertEquals(ChatHistory.LIMIT,h.messages.size());}
 @Test public void unknownFormatIsAnErrorInsteadOfErasingHistory()throws Exception{ChatHistory h=new ChatHistory();h.accepted(Json.obj("messageId","1"),"kept");try{h.merge(new JSONObject(),false);fail();}catch(Exception expected){}assertEquals(1,h.messages.size());}
}
